    0x3C: "Overspeed Warning 21",
    0x3D: "Overspeed Warning 22",
    0x3E: "Overspeed Warning 23",
    0x3F: "Overspeed Warning 24",
    
    // Custom Alarms from your database
    0x44: "Custom Alarm 0x44",
    0x45: "Custom Alarm 0x45",
    0x46: "Custom Alarm 0x46",
    0x49: "Custom Alarm 0x49",
    0x4C: "Custom Alarm 0x4C",
    0x4D: "Custom Alarm 0x4D",
    0x4E: "Custom Alarm 0x4E",
    0x4F: "Custom Alarm 0x4F",
    0x50: "Custom Alarm 0x50",
    0x51: "Custom Alarm 0x51",
    0x52: "Custom Alarm 0x52",
    0x53: "Custom Alarm 0x53",
    0x54: "Custom Alarm 0x54",
    0x58: "Custom Alarm 0x58",
    0x5A: "Custom Alarm 0x5A",
    
    // Extended alarms
    0x76: "Extended Alarm 0x76",
    0x91: "Extended Alarm 0x91",
    0xD1: "Extended Alarm 0xD1",
    
    // Fence Alarms (alternative names from your database)
    0x04: "Fence In",    // Same as Enter Area
    0x05: "Fence Out",   // Same as Exit Area
    
    // Panic button (alternative code)
    0x25: "Panic Button Pressed",
    
    // Add these additional mappings for common GT06N alarms
    0x07: "Arm Alarm",
    0x08: "Disarm Alarm",
    0x38: "Oil Leak Alarm",
    0x39: "Collision Alarm",
    0x3A: "Rollover Alarm",
    0x3B: "Jamming Detection",
    0x41: "Custom Alarm 0x41",
    0x42: "Custom Alarm 0x42",
    0x43: "Custom Alarm 0x43",
    0x47: "Custom Alarm 0x47",
    0x48: "Custom Alarm 0x48",
    0x4A: "Custom Alarm 0x4A",
    0x4B: "Custom Alarm 0x4B",
    0x55: "Custom Alarm 0x55",
