    0x57: "Custom Alarm 0x57",
    0x59: "Custom Alarm 0x59",
    0x5B: "Custom Alarm 0x5B",
    0x5C: "Custom Alarm 0x5C",
    0x5D: "Custom Alarm 0x5D",
    0x5E: "Custom Alarm 0x5E",
